// src/app/core/guards/auth-guard.ts
var authGuard = (route, state) => {
  const accountService = inject2(AccountService);
  const router = inject2(Router);
  if (accountService.currentUser()) {
    return true;
  }
  return accountService.getAuthState().pipe(
    map((auth) => {
      if (auth.isAuthenticated) {
        return true;
      }
      return router.createUrlTree(["/account/login"], {
        queryParams: { returnUrl: state.url }
      });
    })
  );
};

// src/app/core/guards/empty-cart-guard.ts
var emptyCartGuard = (route, state) => {
  const cartService = inject2(CartService);
  const router = inject2(Router);
  const snack = inject2(SnackbarService);
  if (!cartService.cart() || cartService.cart()?.items.length === 0) {
    snack.error("Your cart is empty");
    router.navigateByUrl("/cart");
    return false;
  }
  return true;
};

